import{_ as s,o as a,c as e,ai as n}from"./chunks/framework.BBSijY9B.js";const h=JSON.parse('{"title":"运营与销售","description":"运营和销售人员如何用 Grok Bot 做客户研究、跟进提醒、CRM 维护和活动复盘。","frontmatter":{"related":["/templates/sales-followup","/templates/team-sales-pipeline","/basics/drafts-first"],"title":"运营与销售","description":"运营和销售人员如何用 Grok Bot 做客户研究、跟进提醒、CRM 维护和活动复盘。","section":"roles","order":3,"tags":["角色","运营","销售","CRM"],"sources":["https://x.ai/news/introducing-grok-bot","https://docs.x.ai/grok-bot/overview","https://cursor.com/docs/grok-bot/work"],"wordCount":350,"readingTime":1,"head":[["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:title","content":"运营与销售 | 王宇宙 | WANGXXXL"}],["meta",{"property":"og:description","content":"运营和销售人员如何用 Grok Bot 做客户研究、跟进提醒、CRM 维护和活动复盘。"}],["meta",{"property":"og:url","content":"https://wangxxxl.com/roles/ops-sales"}],["meta",{"property":"og:image","content":"https://wangxxxl.com/og/roles-ops-sales-b7e3944f99.png"}],["meta",{"property":"og:image:alt","content":"运营与销售 · 王宇宙 | WANGXXXL · wangxxxl.com"}],["meta",{"name":"twitter:title","content":"运营与销售 | 王宇宙 | WANGXXXL"}],["meta",{"name":"twitter:description","content":"运营和销售人员如何用 Grok Bot 做客户研究、跟进提醒、CRM 维护和活动复盘。"}],["meta",{"name":"twitter:image","content":"https://wangxxxl.com/og/roles-ops-sales-b7e3944f99.png"}],["meta",{"name":"twitter:image:alt","content":"运营与销售 · 王宇宙 | WANGXXXL · wangxxxl.com"}],["link",{"rel":"canonical","href":"https://wangxxxl.com/roles/ops-sales"}]]},"headers":[],"relativePath":"roles/ops-sales.md","filePath":"roles/ops-sales.md","lastUpdated":1792485206000}'),o={name:"roles/ops-sales.md"};function l(p,t,i,r,c,d){return a(),e("div",null,[...t[0]||(t[0]=[n(`<h1 id="运营与销售" tabindex="-1">运营与销售 <a class="header-anchor" href="#运营与销售" aria-label="Permalink to &quot;运营与销售&quot;">​</a></h1><p>运营和销售的日常，是在客户、表格、邮件、后台之间来回切换。官方介绍里提到的内部用法就包括：销售 Bot 根据通话记录更新 CRM 并起草跟进邮件。这类&quot;多系统、多步骤、有固定节奏&quot;的活，正是 Grok Bot 的强项。</p><h2 id="典型工作" tabindex="-1">典型工作 <a class="header-anchor" href="#典型工作" aria-label="Permalink to &quot;典型工作&quot;">​</a></h2><ul><li>拜访或通话前做客户背景调研。</li><li>通话后整理要点，更新 CRM，起草跟进邮件。</li><li>盯住&quot;该跟进却没跟进&quot;的客户。</li><li>活动结束后汇总数据，写复盘。</li><li>整理常见问题，更新话术库。</li></ul><h2 id="示例提示词" tabindex="-1">示例提示词 <a class="header-anchor" href="#示例提示词" aria-label="Permalink to &quot;示例提示词&quot;">​</a></h2><p><strong>客户调研</strong></p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>下周要拜访这 5 家公司（名单见附件）。每家帮我整理：</span></span>
<span class="line"><span>主营业务、近半年公开新闻、可能的需求点、可以聊的切入话题。只用公开信息，附来源链接。</span></span></code></pre></div><p><strong>通话后处理</strong></p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>附件是今天和某客户的通话记录。请：</span></span>
<span class="line"><span>1）提炼客户的需求、顾虑和下一步；</span></span>
<span class="line"><span>2）在 CRM 里更新这个客户的跟进记录（更新前把要写入的内容给我确认）；</span></span>
<span class="line"><span>3）起草一封跟进邮件，做成草稿。</span></span></code></pre></div><p><strong>跟进提醒</strong></p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>从 CRM 里找出最近 14 天没有任何跟进、但处于&quot;意向&quot;阶段的客户，</span></span>
<span class="line"><span>按预计金额排序，每个写一句建议的跟进理由。</span></span></code></pre></div><p><strong>活动复盘</strong></p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>附件是这次线上活动的报名表和后台数据导出。帮我算：报名数、到场率、各渠道带来的报名占比，</span></span>
<span class="line"><span>再对比上次活动（数据在 /workspace/活动/上次/），写一份一页的复盘。</span></span></code></pre></div><h2 id="推荐例程" tabindex="-1">推荐例程 <a class="header-anchor" href="#推荐例程" aria-label="Permalink to &quot;推荐例程&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>每个工作日早上 8:30，检查 CRM 里今天到期的跟进任务和 14 天未跟进的意向客户，</span></span>
<span class="line"><span>为每个客户起草一句跟进开场白，汇总发给我。不要联系任何客户。</span></span></code></pre></div><div class="tip custom-block"><p class="custom-block-title">先连好 CRM</p><p>如果你的 CRM 有连接器，优先用连接器；没有的话，Bot 也可以通过浏览器在网页后台操作，第一次登录由你接管完成。</p></div><div class="warning custom-block"><p class="custom-block-title">常见坑</p><ul><li><strong>让 Bot 直接群发邮件</strong>：对客户的每一封邮件都应走草稿，由你按发送。</li><li><strong>CRM 写入不确认</strong>：写入前先让它给出&quot;将要修改的字段和新值&quot;，避免批量写错。</li><li><strong>客户隐私</strong>：客户名单、联系方式放在共享电脑上时注意范围，项目结束后清理。</li><li><strong>调研信息不注明来源</strong>：口头说给客户听的信息，一定要能追溯到出处。</li></ul></div>`,17)])])}const u=s(o,[["render",l]]);export{h as __pageData,u as default};
